		// of the first token of this run reaches two tokens behind it.
		rows := PLERows(g.pleCfg, g.ids)[g.past*g.pleCfg.NHeads:]
		pleEmbd, err = g.m.PLEGather(rows, g.pleCfg.NHeads, g.pleCfg.HeadDim)
