 74	#include "llm_common.glsl"
 75	
 76	#ifndef LPC
 77	#define LPC 16          // lanes per state column
 78	#endif
 79	#ifndef WAVES
 80	#define WAVES 1         // waves per workgroup, sharing the staged q and k
 81	#endif
 82	
 83	#define WAVE 64
 84	#define S_V 128                 // head dim; the host checks the checkpoint
 85	#define COLS (WAVE / LPC)       // state columns a wave owns
 86	#define RPL (S_V / LPC)         // state elements a lane holds
 87	
 88	#ifndef PREFETCH
 89	#define PREFETCH 0
 90	#endif
 91	
 92	#ifndef QKREG
 93	#if (S_V / LPC) <= 32
 94	#define QKREG 1
 95	#else
 96	#define QKREG 0
 97	#endif
 98	#endif
