108	    uint h = gl_WorkGroupID.x;                  // value head
109	    uint tid = gl_LocalInvocationID.x;
110	    uint wave = tid / WAVE;
111	    uint w = tid % WAVE;
112	    uint lane = w % LPC;                        // position inside the column
113	    uint col = (gl_WorkGroupID.y * WAVES + wave) * COLS + w / LPC;
114	
115	    uint hk = h % pc.kvHeads;
116	    uint qk = pc.kvHeads * pc.headDim;
117	    uint cw = 2u * qk + pc.heads * pc.headDim;
118	    uint qcol = hk * S_V;
119	    uint kcol = qk + hk * S_V;
120	    uint vcol = 2u * qk + h * S_V;
121	    float scale = inversesqrt(float(S_V));
122	
123	    uint sbase = pc.ssmStateOff + h * (S_V * S_V) + col * S_V;
124	    float s[RPL];
125	    [[unroll]] for (uint r = 0u; r < RPL; r++) {
126	        s[r] = act[sbase + r * LPC + lane];
127	    }
128	
129	#if QKREG && PREFETCH
130	    // A one-deep software pipeline, and the thing it is working around is an
131	    // aliasing rule rather than a latency: every tensor this kernel touches
132	    // lives in the same read-write SSBO (llm_common.glsl's four-arena
133	    // contract), so the store at the end of token t may, as far as the
134	    // compiler can prove, be the load at the start of token t+1. It therefore
135	    // cannot hoist the loads across the store, and each of 512 iterations
136	    // pays a full memory round trip on its critical path. llama.cpp's kernel
137	    // has seven separate bindings, five of them `readonly`, and gets the
138	    // pipelining for free.
139	    //
140	    // Issuing the next token's operands *before* this token's arithmetic puts
141	    // one iteration of latency in flight. It costs 2*RPL more registers,
142	    // which is why it is a rung and not the kernel.
143	    float qn[RPL], kn[RPL], vn, gn, bn;
144	    {
145	        uint row = pc.normOff;
146	        [[unroll]] for (uint r = 0u; r < RPL; r++) {
147	            qn[r] = act[row + qcol + r * LPC + lane];
148	            kn[r] = act[row + kcol + r * LPC + lane];
149	        }
150	        vn = act[row + vcol + col];
151	        gn = act[pc.ssmGateOff + h];
152	        bn = act[pc.ssmBetaOff + h];
153	    }
154	    for (uint t = 0u; t < pc.tokens; t++) {
155	        float qr[RPL], kr[RPL];
156	        [[unroll]] for (uint r = 0u; r < RPL; r++) {
157	            qr[r] = qn[r];
158	            kr[r] = kn[r];
159	        }
160	        float v = vn, g = exp(gn), beta = bn;
161	        if (t + 1u < pc.tokens) {
162	            uint row = pc.normOff + (t + 1u) * cw;
163	            [[unroll]] for (uint r = 0u; r < RPL; r++) {
164	                qn[r] = act[row + qcol + r * LPC + lane];
165	                kn[r] = act[row + kcol + r * LPC + lane];
166	            }
167	            vn = act[row + vcol + col];
168	            gn = act[pc.ssmGateOff + (t + 1u) * pc.heads + h];
169	            bn = act[pc.ssmBetaOff + (t + 1u) * pc.heads + h];
170	        }
171	
172	        float kv = 0.0;
173	        [[unroll]] for (uint r = 0u; r < RPL; r++) {
174	            kv += g * s[r] * kr[r];
175	        }
176	#if LPC == WAVE
177	        kv = subgroupAdd(kv);
178	#elif LPC > 1
179	        kv = subgroupClusteredAdd(kv, LPC);
180	#endif
181	        float delta = (v - kv) * beta;
182	
183	        float o = 0.0;
184	        [[unroll]] for (uint r = 0u; r < RPL; r++) {
185	            s[r] = g * s[r] + kr[r] * delta;
186	            o += s[r] * qr[r];
187	        }
