189	        o = subgroupAdd(o);
190	#elif LPC > 1
191	        o = subgroupClusteredAdd(o, LPC);
192	#endif
193	        if (lane == 0u) {
194	            act[pc.outOff + (t * pc.heads + h) * S_V + col] = o * scale;
195	        }
196	    }
197	#else
198	    for (uint t = 0u; t < pc.tokens; t++) {
199	        uint row = pc.normOff + t * cw;
200	#if QKREG
201	        // The reference's shape: each lane reads the 128/LPC components of q
202	        // and k it will multiply, and nothing crosses LDS.
203	        float qr[RPL], kr[RPL];
204	        [[unroll]] for (uint r = 0u; r < RPL; r++) {
205	            qr[r] = act[row + qcol + r * LPC + lane];
206	            kr[r] = act[row + kcol + r * LPC + lane];
207	        }
208	#define QV(r) qr[r]
209	#define KV(r) kr[r]
210	#else
211	        // One staging pass for the whole workgroup: 256 floats, however many
212	        // columns the waves between them own.
213	        for (uint i = tid; i < S_V; i += WAVE * WAVES) {
214	            qs[i] = act[row + qcol + i];
