220	#endif
221	
222	        float g = exp(act[pc.ssmGateOff + t * pc.heads + h]);
223	        float beta = act[pc.ssmBetaOff + t * pc.heads + h];
224	
225	        float kv = 0.0;
226	        [[unroll]] for (uint r = 0u; r < RPL; r++) {
227	            kv += g * s[r] * KV(r);
228	        }
229	#if LPC == WAVE
230	        kv = subgroupAdd(kv);
231	#elif LPC > 1
232	        kv = subgroupClusteredAdd(kv, LPC);
233	#endif
234	        float delta = (act[row + vcol + col] - kv) * beta;
235	
236	        float o = 0.0;
237	        [[unroll]] for (uint r = 0u; r < RPL; r++) {
238	            s[r] = g * s[r] + KV(r) * delta;
239	            o += s[r] * QV(r);
240	        }
241	#if LPC == WAVE
242	        o = subgroupAdd(o);
243	#elif LPC > 1
244	        o = subgroupClusteredAdd(o, LPC);
245	#endif
