250	        barrier();
251	#endif
252	#undef QV
253	#undef KV
254	    }
255	
256	#endif
257	
258	    [[unroll]] for (uint r = 0u; r < RPL; r++) {
259	        act[sbase + r * LPC + lane] = s[r];
260	    }
261	}

