package llm

import (
	"testing"
)

// Temporary bisection harness for P5c. Not a gate.
func TestSpecDebug(t *testing.T) {
	const (
		layers = 4
		nTok   = 512
		prefix = 480
	)
	m, tr := fixtures4k(t)
	all, _, err := tr.Tokens()
	if err != nil {
		t.Fatal(err)
	}
	ids := all[:nTok]
	dev, done := newTestDevice(t)
	t.Cleanup(done)
	g, err := NewGraph(dev, m, GraphOpts{MaxTokens: nTok, NKV: nTok + 16, Layers: layers, NoHead: true})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(g.Destroy)
	if err := g.PinSchedule(true); err != nil {
		t.Fatal(err)
	}
	norm, err := g.Hidden(ids)
	if err != nil {
		t.Fatal(err)
	}
	want := append([]float32(nil), norm...)
	wrong := ids[7]

	step := func(t *testing.T, spec, reject bool, chunk int) {
		if err := g.Reset(); err != nil {
			t.Fatal(err)
		}
		if err := g.Append(ids[:prefix]); err != nil {
			t.Fatal(err)
		}
		if err := g.Speculate(spec); err != nil {
			t.Fatal(err)
		}
		defer g.Speculate(false)
		var got []float32
		for at := prefix; at < nTok; at += chunk {
			n := minInt(chunk, nTok-at)
			if reject {
				was, wasIds := g.Past(), len(g.Ids())
				pass := append(append([]int32(nil), ids[at:at+n]...), wrong)
				if err := g.Append(pass); err != nil {
					t.Fatal(err)
				}
				if spec {
					if err := g.Rewind(); err != nil {
						t.Fatal(err)
					}
				} else if err := g.rewindPosition(was, wasIds); err != nil {
					t.Fatal(err)
				}
			}
			if at+n == nTok {
				got, err = g.HiddenExtend(ids[at : at+n])
			} else {
				err = g.Append(ids[at : at+n])
			}
			if err != nil {
				t.Fatal(err)
			}
			if spec {
				if err := g.Commit(); err != nil {
					t.Fatal(err)
				}
			}
		}
		r, cerr := compare(got, want)
		if cerr != nil {
			t.Fatal(cerr)
		}
		t.Logf("spec=%v reject=%v chunk=%d: %v", spec, reject, chunk, r)
	}

	t.Run("plain,chunk1", func(t *testing.T) { step(t, false, false, 1) })
	t.Run("spec,commit,chunk1", func(t *testing.T) { step(t, true, false, 1) })
	t.Run("spec,commit,chunk2", func(t *testing.T) { step(t, true, false, 2) })
	t.Run("spec,reject,chunk1", func(t *testing.T) { step(t, true, true, 1) })
}

