cat > llm/chunk_probe_test.go <<'EOF'
package llm

import "testing"

func TestChunkProbe(t *testing.T) {
	const (
		nTok   = 512
		prefix = 480
	)
	m, tr := fixtures4k(t)
	all, _, err := tr.Tokens()
	if err != nil {
		t.Fatal(err)
	}
	ids := all[:nTok]
	dev, done := newTestDevice(t)
	t.Cleanup(done)
	for _, layers := range []int{1, 2, 3, 4} {
		g, err := NewGraph(dev, m, GraphOpts{MaxTokens: nTok, NKV: nTok + 16, Layers: layers, NoHead: true})
		if err != nil {
			t.Fatal(err)
		}
		if err := g.PinSchedule(true); err != nil {
			t.Fatal(err)
		}
		if err := g.Prefill(ids); err != nil {
			t.Fatal(err)
		}
		want := append([]float32(nil), g.Residual()...)
		wide := len(want) / nTok
		for _, chunk := range []int{1, 2, 3, 4} {
			if err := g.Reset(); err != nil {
				t.Fatal(err)
			}
			if err := g.Append(ids[:prefix]); err != nil {
				t.Fatal(err)
			}
			bad := -1
			for at := prefix; at < nTok; at += chunk {
				n := minInt(chunk, nTok-at)
				if err := g.Append(ids[at : at+n]); err != nil {
					t.Fatal(err)
				}
				got := g.Residual()
				r, _ := compare(got[:n*wide], want[at*wide:(at+n)*wide])
				if r.rms > 1e-3 && bad < 0 {
					bad = at
					t.Logf("layers=%d chunk=%d: first divergence at %d: %v", layers, chunk, at, r)
				}
			}
			if bad < 0 {
				t.Logf("layers=%d chunk=%d: clean", layers, chunk)
			}
		}
		g.Destroy()
	}
}
EOF
timeout 900 go test ./llm/ -run TestChunkProbe -v 2>&1 | grep -E "layers=|FAIL|ok "

