    // MODE 0 wrote. One row per tile — see the header.
    [[unroll]] for (uint r = 0u; r < MAXROWS; r++) {
        if (r >= ROWS) {
            continue;
        }
#if MODE == 0
        uint p = actu[pc.moePermOff + rowStart + r];
        uint aBase = pc.xnOff + (p / slots) * pc.lda;
#else
        uint aBase = pc.ctxOff + (rowStart + r) * pc.ldCtx;
#endif
        for (uint k = tid; k < pc.gemmK; k += LANES) {
            sA[r * AKMAX + k] = hact[aBase + k];
        }
    }
#if QFMT == FMT_IQ4NL
    if (tid < 16u) {
        kIQ4[tid] = iq4nlConst(tid);
    }
#endif
    barrier();

    uint lane = tid & (LPR - 1u);
    uint n0 = gl_WorkGroupID.x * NCOL + (tid / LPR);
    uint rowBytes = (pc.gemmK / QK) * QB;
    uint bankRow = expert * pc.gemmN + n0;
    uint rb0 = pc.bOff + bankRow * rowBytes;
#if MODE == 0
    uint rb1 = pc.moeBOff2 + bankRow * rowBytes;
#endif

    uint nqd = (pc.gemmK / QK) * QSDB;
    // The row loop is outside the dword loop rather than inside it, because
    // what is scarce here is registers and not bank traffic: the bank row is
    // in the L1 after the first pass over it, where MAXROWS pairs of live
    // accumulators plus the unpack's temporaries are not free. The weight is
    // still read once per row from DRAM's point of view, which is the claim
    // that matters.
    [[unroll]] for (uint r = 0u; r < MAXROWS; r++) {
        if (r >= ROWS) {
            continue;
        }
        float acc0 = 0.0;
#if MODE == 0
        float acc1 = 0.0;
#endif
        for (uint d = lane; d < nqd; d += LPR) {
            acc0 += dotDword(rb0, d, r);
#if MODE == 0
            acc1 += dotDword(rb1, d, r);
#endif
        }

        acc0 = subgroupClusteredAdd(acc0, LPR);
#if MODE == 0
        acc1 = subgroupClusteredAdd(acc1, LPR);
#endif
        if (lane != 0u) {
            continue;
        }
#if MODE == 0
        // `ggml_swiglu_split` on the two sums, so the [rows, 640] pair the
        // reference materialises never exists here either.
        hact[pc.ctxOff + (rowStart + r) * pc.ldCtx + n0] =
            float16_t(acc0 * sigmoidf(acc0) * acc1);
#else
        act[pc.gatedOff + (rowStart + r) * pc.nEmbd + n0] = acc0;
#endif
    }
}

