cat > llm/chunk_probe_test.go <<'EOF'
package llm

import "testing"

func TestChunkProbe(t *testing.T) {
	const (
		nTok   = 512
		prefix = 480
		layers = 1
		chunk  = 2
	)
	m, tr := fixtures4k(t)
	all, _, err := tr.Tokens()
	if err != nil {
		t.Fatal(err)
	}
	ids := all[:nTok]
	dev, done := newTestDevice(t)
	t.Cleanup(done)
	g, err := NewGraph(dev, m, GraphOpts{MaxTokens: nTok, NKV: nTok + 16, Layers: layers, NoHead: true})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(g.Destroy)
	if err := g.PinSchedule(true); err != nil {
		t.Fatal(err)
	}
	if err := g.Prefill(ids); err != nil {
		t.Fatal(err)
	}
	want := append([]float32(nil), g.Residual()...)
	wide := len(want) / nTok

	probe := func(name string, plan func()) {
		if err := g.PinSchedule(true); err != nil {
			t.Fatal(err)
		}
		if err := g.Reset(); err != nil {
			t.Fatal(err)
		}
		if err := g.Append(ids[:prefix]); err != nil {
			t.Fatal(err)
		}
		if err := g.moe.Resize(chunk); err != nil {
			t.Fatal(err)
		}
		plan()
		worst := cmpResult{}
		for at := prefix; at < nTok; at += chunk {
			n := minInt(chunk, nTok-at)
			if err := g.Append(ids[at : at+n]); err != nil {
				t.Fatal(err)
			}
			r, _ := compare(g.Residual()[:n*wide], want[at*wide:(at+n)*wide])
			if r.rms > worst.rms {
				worst = r
			}
		}
		t.Logf("%-22s worst %v", name, worst)
	}

	gemm := func() {
		if err := g.moe.SetPlan(MoEM2, MoEM2); err != nil {
			t.Fatal(err)
		}
		if err := g.moe.SetRouter(MoERouterGEMM); err != nil {
			t.Fatal(err)
		}
	}
	probe("all GEMM", gemm)
	probe("routed GEMV", func() {
		gemm()
		if err := g.moe.SetPlan(MoEV64W4, MoEV16W4); err != nil {
			t.Fatal(err)
		}
		if err := g.moe.SetSharedPlan(MoEM2, MoEM2); err != nil {
			t.Fatal(err)
		}
	})
	probe("shared GEMV", func() {
		gemm()
		if err := g.moe.SetSharedPlan(MoEV64W4, MoEV32W4); err != nil {
			t.Fatal(err)
		}
	})
	probe("router GEMV", func() {
		gemm()
		if err := g.moe.SetRouter(MoERouterK40); err != nil {
			t.Fatal(err)
		}
	})
	probe("routed up GEMV only", func() {
		gemm()
		if err := g.moe.SetPlan(MoEV64W4, MoEM2); err != nil {
			t.Fatal(err)
		}
		if err := g.moe.SetSharedPlan(MoEM2, MoEM2); err != nil {
			t.Fatal(err)
		}
	})
	probe("routed down GEMV only", func() {
		gemm()
		if err := g.moe.SetPlan(MoEM2, MoEV16W4); err != nil {
			t.Fatal(err)
		}
		if err := g.moe.SetSharedPlan(MoEM2, MoEM2); err != nil {
			t.Fatal(err)
		}
	})
}
EOF
timeout 900 go test ./llm/ -run TestChunkProbe -v 2>&1 | grep -E "worst|FAIL|ok |\.go:"

