p='llm/gpu_deltanet.go'; s=open(p).read()

old = """	stateStride, winStride int
	stateSlot              int
	stateSpec              bool"""
new = """	stateStride, winStride int
	stateSlot              int
	stateSpec              bool
	// slots is 2 when this block was staged for speculation and 1 otherwise.
	// **It is a staging choice and not a runtime one** (P5c): the second slot
	// is 113.25 MB of state and 7.13 MB of ring across 36 layers, which is
	// 120.75 MB a product run has no use for, so a graph that will never
	// speculate does not allocate it and `Speculate(true)` refuses.
	slots int"""
assert old in s; s = s.replace(old, new, 1)

old = """	// Two slots of each carried tensor, not one (P5c). The second is what a
	// speculative verification pass writes so that a rejection costs nothing:
	// 7.13 MB of ring and 113.25 MB of state at 36 layers, against 78.5 GB
	// resident. The slots of one layer are **adjacent**, so a slot is a
	// layer's base plus a stride and neither the kernels nor the staging
	// notice.
	g.winStride = hist * g.qkvN()
	g.stateStride = c.StateSize()
	g.aWin = alloc(nLayers * 2 * g.winStride)"""
new = """	// One slot of each carried tensor, or two when this block was staged for
	// speculation (P5c). The second is what a rewindable verification pass
	// writes so that a rejection costs nothing — 7.13 MB of ring and 113.25 MB
	// of state at 36 layers — and a run that will never speculate should not
	// carry it, which is why `slots` is set before `alloc` and not by a
	// setter. The slots of one layer are **adjacent**, so a slot is a layer's
	// base plus a stride and neither the kernels nor the staging notice.
	if g.slots <= 0 {
		g.slots = 1
	}
	g.winStride = hist * g.qkvN()
	g.stateStride = c.StateSize()
	g.aWin = alloc(nLayers * g.slots * g.winStride)"""
assert old in s; s = s.replace(old, new, 1)

s = s.replace("	g.aState = alloc(nLayers * 2 * g.stateStride)",
              "	g.aState = alloc(nLayers * g.slots * g.stateStride)", 1)
s = s.replace("			state:  g.aState + uint32(i*2*g.stateStride),\n			win:    g.aWin + uint32(i*2*g.winStride),",
              "			state:  g.aState + uint32(i*g.slots*g.stateStride),\n			win:    g.aWin + uint32(i*g.slots*g.winStride),", 1)

# Reset zeroes however many slots there are.
s = s.replace("""	for slot := 0; slot < 2; slot++ {
		g.abuf.ZeroFloat32At(int(g.stateAt(layer, slot)), c.StateSize())
		g.abuf.ZeroFloat32At(int(g.winAt(layer, slot)), (c.Conv-1)*g.qkvN())
	}""",
"""	for slot := 0; slot < g.slots; slot++ {
		g.abuf.ZeroFloat32At(int(g.stateAt(layer, slot)), c.StateSize())
		g.abuf.ZeroFloat32At(int(g.winAt(layer, slot)), (c.Conv-1)*g.qkvN())
	}""", 1)

old = """func (g *DeltaNetGPU) Speculate(on bool) { g.stateSpec = on }"""
new = """func (g *DeltaNetGPU) Speculate(on bool) error {
	if on && g.slots < 2 {
		return fmt.Errorf("llm: this block was staged with one state slot; a rewindable pass needs two " +
			"(GraphOpts.Speculative)")
	}
	g.stateSpec = on
	return nil
}"""
assert old in s; s = s.replace(old, new, 1)
open(p,'w').write(s)
print("dn ok")
